            {'SUCCESS':[(2.9e9,.30),(3.1e9,.32)],'INLINE':[(2.6e9,.28),(2.8e9,.30)],'FAILURE':[(2.0e9,.22),(2.3e9,.25)]},
            {'SUCCESS':[(3.0e9,.32),(3.4e9,.35)],'INLINE':[(2.5e9,.28),(2.7e9,.30)],'FAILURE':[(2.0e9,.22),(2.3e9,.25)]},
